import { useData } from 'vike-react/useData';
import { useTranslation } from 'react-i18next';
import { useState } from 'react';
import type { PageData } from './+data';
import { Head } from './+Head';
import { Box, Stack, HStack, Divider, styled } from 'styled-system/jsx';
import { Heading } from '~/components/ui/heading';
import { Text } from '~/components/ui/text';
import { Link } from '~/components/ui/link';
import { Tabs } from '~/components/ui/tabs';
import MainContentAndRightSidebar from '~/components/layout/MainContentAndRightSidebar';
import { Tweet } from '~/components/bluebird/Tweet';
import type { PrunedTweet } from '~/utils/prune-tweets';
import { characters } from '~/utils/character-data';
import { MonthYearList } from '~/components/bluebird/MonthYearList';
import { monthYearToString } from '~/utils/date';
import { sortAuthorsByCustomOrder } from '~/utils/bluebirdAuthors';
import { TabContentSection, CharacterTweet } from '~/components/bluebird/MonthlySummaryComponents';

export default function Page() {
  const { t, i18n } = useTranslation();
  const data = useData<PageData>();
  const [selectedMonth, setSelectedMonth] = useState<string | null>(
    data.summaries.length > 0 ? data.summaries[0].month : null
  );

  const currentSummary = data.summaries.find((s) => s.month === selectedMonth);
  const isJapanese = i18n.language === 'ja';
  const summary = isJapanese ? currentSummary?.summaryJa : currentSummary?.summaryEn;
  const tweets = isJapanese ? currentSummary?.tweetsJa : currentSummary?.tweetsEn;

  // Helper function to get character info from username
  const getCharacterInfo = (username: string) => {
    const character = characters.find((char) =>
      char.profile.some(
        (profileItem) =>
          profileItem.startsWith('Xアカウント:') &&
          profileItem.toLowerCase().includes(username.toLowerCase())
      )
    );
    return {
      name: isJapanese ? character?.fullName : character?.englishName,
      image: character?.prePublicData?.image,
      color: character?.colorCode
    };
  };

  // Helper function to get tweet from URL
  const getTweetFromUrl = (url: string): PrunedTweet | null => {
    // Extract tweet ID from URL
    const match = url.match(/status\/(\d+)/);
    const tweetId = match ? match[1] : null;

    if (!tweetId || !tweets || !tweets[tweetId]) return null;
    return tweets[tweetId];
  };

  return (
    <>
      <Head />
      <MainContentAndRightSidebar
        rightSidebarContent={({ close }) => (
          <Box position="sticky" top="0" p="4">
            <Stack gap="3">
              <Heading size="md" fontWeight="semibold">
                {t('bluebird.monthlySummary.selectMonth')}
              </Heading>
              <MonthYearList
                monthsYears={data.summaries.map((s) => ({
                  monthYear: s.month,
                  count: 0,
                  firstTweetId: ''
                }))}
                currentMonthYear={selectedMonth}
                setSelectedMonthYear={(monthYear) => setSelectedMonth(monthYear)}
                closeSidebar={close}
                latestTweetId={null}
                handleSelectTweet={() => {}}
              />
            </Stack>
            <Box borderRadius="md" mt="4" p="2" color="text.subtle" fontSize="xs" bg="bg.subtle">
              {t('bluebird.sidebar.aiTranslationWarning')}
            </Box>
          </Box>
        )}
      >
        <Box layerStyle="contentHeight" w="full" p={{ base: '4', md: '6' }} overflowY="auto">
          {selectedMonth && summary ? (
            <Stack gap="8">
              {/* Header */}
              <Box>
                <Heading as="h1" size="3xl" mb="2">
                  {monthYearToString(selectedMonth, i18n.language)}
                </Heading>
                <Text size="lg" color="fg.muted">
                  {t('bluebird.monthlySummary.title')}
                </Text>
              </Box>

              {/* TL;DR Section */}
              <Box
                borderLeft="4px solid"
                borderLeftColor="blue.default"
                borderRadius="lg"
                p="5"
                bg="blue.2"
              >
                <Heading size="sm" mb="2" letterSpacing="wider" textTransform="uppercase">
                  {t('bluebird.monthlySummary.tldr')}
                </Heading>
                <Text size="lg" lineHeight="relaxed">
                  {summary.tldr}
                </Text>
              </Box>

              {/* Monthly Highlights */}
              <Box>
                <Heading size="xl" mb="3">
                  {t('bluebird.monthlySummary.monthlyHighlights')}
                </Heading>
                <Text size="lg" mb="6" color="fg.muted">
                  {summary.monthly_highlights.overall_summary}
                </Text>

                <Tabs.Root defaultValue="events">
                  <Tabs.List mb="4">
                    <Tabs.Trigger value="events">
                      {t('bluebird.monthlySummary.majorEvents')} (
                      {summary.monthly_highlights.major_events.length})
                    </Tabs.Trigger>
                    <Tabs.Trigger value="topics">
                      {t('bluebird.monthlySummary.pickupTopics')} (
                      {summary.monthly_highlights.pickup_topics.length})
                    </Tabs.Trigger>
                  </Tabs.List>

                  <Tabs.Content value="events">
                    <TabContentSection
                      items={summary.monthly_highlights.major_events}
                      getTweetFromUrl={getTweetFromUrl}
                      type="event"
                    />
                  </Tabs.Content>

                  <Tabs.Content value="topics">
                    <TabContentSection
                      items={summary.monthly_highlights.pickup_topics}
                      getTweetFromUrl={getTweetFromUrl}
                      type="topic"
                    />
                  </Tabs.Content>
                </Tabs.Root>
              </Box>

              <Divider />

              {/* Character Activity */}
              <Box>
                <Heading size="xl" mb="6">
                  {t('bluebird.monthlySummary.characterActivity')}
                </Heading>
                <Stack gap="4">
                  {sortAuthorsByCustomOrder(
                    Object.entries(summary.character_activity_summary).map(
                      ([username, activity]) => ({
                        userName: username,
                        activity
                      })
                    )
                  ).map(({ userName: username, activity }) => {
                    const charInfo = getCharacterInfo(username);
                    return (
                      <Box
                        key={`char-${selectedMonth}-${username}-${i18n.language}`}
                        borderLeft="3px solid"
                        borderLeftColor={'blue.default'}
                        borderRadius="lg"
                        p="5"
                        bg="blue.3"
                      >
                        <HStack gap="3" alignItems="center" mb="4">
                          {charInfo.image && (
                            <Box flexShrink="0" borderRadius="full" w="12" h="12" overflow="hidden">
                              <styled.img
                                src={charInfo.image}
                                alt={charInfo.name || username}
                                transform="scale(1.1)"
                                objectFit="cover"
                                w="12"
                                h="12"
                              />
                            </Box>
                          )}
                          <Box>
                            <Heading size="lg" color={charInfo.color || 'fg.default'}>
                              {charInfo.name || username}
                            </Heading>
                            <Text size="sm" color="fg.muted">
                              @{username}
                            </Text>
                          </Box>
                        </HStack>
                        <Text mb="4" lineHeight="relaxed">
                          {activity.summary}
                        </Text>
                        {activity.featured_tweets.length > 0 && (
                          <Box>
                            <Text size="sm" mb="3" color="fg.muted" fontWeight="semibold">
                              {t('bluebird.monthlySummary.featuredTweets')}
                            </Text>
                            <Stack gap="3">
                              {activity.featured_tweets.slice(0, 2).map((featuredTweet, idx) => {
                                const tweet = getTweetFromUrl(featuredTweet.tweet_url);
                                return (
                                  <Box key={`char-tweet-${username}-${idx}-${i18n.language}`}>
                                    <CharacterTweet
                                      featuredTweet={featuredTweet}
                                      tweet={tweet}
                                      useEnglishName={i18n.language === 'en'}
                                    />
                                  </Box>
                                );
                              })}
                            </Stack>
                          </Box>
                        )}
                      </Box>
                    );
                  })}
                </Stack>
              </Box>

              <Divider />

              {/* Featured Tweets */}
              <Box>
                <Heading size="xl" mb="6">
                  {t('bluebird.monthlySummary.featuredTweets')}
                </Heading>
                <Stack gap="4" gridTemplateColumns={{ base: '1fr', lg: 'repeat(2, 1fr)' }}>
                  {summary.featured_tweets.map((featuredTweet, idx) => {
                    const tweet = getTweetFromUrl(featuredTweet.tweet_url);
                    const featuredKey = `featured-${selectedMonth}-${idx}-${i18n.language}`;
                    return tweet ? (
                      <Tweet
                        key={featuredKey}
                        tweet={tweet}
                        useEnglishName={i18n.language !== 'ja'}
                      />
                    ) : (
                      <Box
                        key={featuredKey}
                        border="1px solid"
                        borderColor="border.default"
                        borderRadius="md"
                        p="4"
                        _hover={{ bg: 'bg.subtle' }}
                      >
                        <HStack justify="space-between">
                          <Box>
                            <Text fontWeight="semibold">@{featuredTweet.username}</Text>
                            <Text size="sm" color="fg.muted">
                              {featuredTweet.date}
                            </Text>
                          </Box>
                          <Link href={featuredTweet.tweet_url} target="_blank">
                            {t('bluebird.monthlySummary.viewTweet')} →
                          </Link>
                        </HStack>
                      </Box>
                    );
                  })}
                </Stack>
              </Box>
            </Stack>
          ) : (
            <Box py="20" textAlign="center">
              <Heading size="xl" mb="2" color="fg.muted">
                {t('bluebird.monthlySummary.noSummaries')}
              </Heading>
              <Text color="fg.muted">{t('bluebird.monthlySummary.selectMonthToView')}</Text>
            </Box>
          )}
        </Box>
      </MainContentAndRightSidebar>
    </>
  );
}
